 "content": "def transform(grid):
    """Extend every straight line between consecutive same-color markers.

    The input contains sparse markers of one color on a uniform field. Fill
    the row/column intervals between consecutive markers with 2, retaining the
    endpoint markers and untouched cells.
    """
    h, w = len(grid), len(grid[0])
    # Marker is the least frequent color; field is the dominant color.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=counts.get)
    field = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # In each row/column, connect consecutive markers across field cells.
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            if all(grid[r][c] == field for c in range(a + 1, b)):
                for c in range(a + 1, b):
                    out[r][c] = 2
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            if all(grid[r][c] == field for r in range(a + 1, b)):
                for r in range(a + 1, b):
                    out[r][c] = 2
    return out

