            for c in range(a+1,b):
                if grid[r][c] != marker: out[r][c] = 2
        elif len(anchors) > 2:
            # in multi-anchor lines, only fill gaps where original field is continuous
            for a,b in zip(anchors, anchors[1:]):
                if b-a > 1 and all(grid[r][x] != marker for x in range(a+1,b)):
                    for x in range(a+1,b): out[r][x]=2
    for c in range(w):
