 "content": "from collections import Counter


def transform(grid):
    """Recolor short field runs enclosed by the sparse marker color."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    field = counts.most_common(1)[0][0]
