 "content": "from collections import Counter


def transform(grid):
    """Fill field-color intervals between consecutive sparse markers with 2."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=counts.get)
    field = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Connect consecutive marker cells on each row, only across uninterrupted
    # field-colored cells. Markers and unrelated cells remain unchanged.
    for r in range(h):
        anchors = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(anchors, anchors[1:]):
            if b > a + 1 and all(grid[r][c] == field for c in range(a + 1, b)):
                for c in range(a + 1, b):
                    out[r][c] = 2

    # Same rule on columns.
    for c in range(w):
        anchors = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(anchors, anchors[1:]):
            if b > a + 1 and all(grid[r][c] == field for r in range(a + 1, b)):
                for r in range(a + 1, b):
                    out[r][c] = 2
    return out


