def transform(grid):
    """Connect each marker pixel to the next marker in the same row/column."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=counts.get)
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # The examples show that markers in a line define a path; all intervening
    # background cells are recolored, including long stretches between points.
    for r in range(h):
        positions = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2

    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out


