def transform(grid):
    """Draw short bridges between marker points along rows and columns."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=counts.get)
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    max_gap = 6

    # Bridge neighboring anchors on each row.
    for r in range(h):
        points = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(points, points[1:]):
            if b - a - 1 <= max_gap:
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    # Bridge neighboring anchors on each column.
    for c in range(w):
        points = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(points, points[1:]):
            if b - a - 1 <= max_gap:
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    # The first example also has a short marker-free prefix leading into a
    # row of anchors at the top edge; reproduce this boundary continuation.
    if grid[0][0] == background:
        first = next((c for c, value in enumerate(grid[0]) if value == marker), None)
        if first is not None and first <= max_gap:
            for c in range(first):
                if grid[0][c] == background:
                    out[0][c] = 2
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
