def transform(grid):
    """Connect collinear markers and extend aligned strokes to nearby lines."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=counts.get)
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Connect markers which share a row or column; preserve other marker cells.
    for r in range(h):
        positions = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out


