 "content": "from collections import Counter


def transform(grid):
    """Recolor short background gaps between consecutive marker runs with 2."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=counts.get)
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    def scan(line, put):
        runs = []
        i = 0
        while i < len(line):
            if line[i] != marker:
                i += 1
                continue
            j = i
            while j + 1 < len(line) and line[j + 1] == marker:
                j += 1
            runs.append((i, j))
            i = j + 1
        for (_, end), (start, _) in zip(runs, runs[1:]):
            gap = start - end - 1
            if 1 <= gap <= 3 and all(line[k] == background for k in range(end + 1, start)):
                for k in range(end + 1, start):
                    put(k)

    for r in range(h):
        scan(grid[r], lambda c, r=r: out[r].__setitem__(c, 2))
    for c in range(w):
        scan([grid[r][c] for r in range(h)], lambda r, c=c: out[r].__setitem__(c, 2))
    return out
